import React, { useState } from "react";
import { ArrowLeft, Sun, Moon } from "lucide-react";

const MARK_TEAL = "data:image/png;base64,";
const MARK_GOLD = "data:image/png;base64,";

const ACCENT_LIGHT = "#1D95A6";
const ACCENT_DARK = "#D6A429";

export default function App() {
  const [dark, setDark] = useState(false);
  const accent = dark ? ACCENT_DARK : ACCENT_LIGHT;
  const accentContrast = dark ? "#1A1305" : "#FFFFFF";
  const accentBorderSoft = dark ? "rgba(214,164,41,0.45)" : "rgba(29,149,166,0.35)";

  return (
    <div
      dir="rtl"
      className="min-h-screen flex flex-col items-center justify-center relative transition-colors duration-300 px-6"
      style={{
        fontFamily: "'Tajawal', 'Segoe UI', sans-serif",
        backgroundColor: dark ? "#0F1115" : "#F7F2E7",
      }}
    >
      <style>{`
        .ain-accent-solid { background-color: ${accent}; color: ${accentContrast}; }
        .ain-accent-text { color: ${accent}; }
        .ain-accent-hover:hover { border-color: ${accentBorderSoft}; }
      `}</style>

      <button
        onClick={() => setDark((d) => !d)}
        className={`ain-accent-hover absolute top-6 left-6 flex items-center gap-2 rounded-full px-3 py-1.5 text-xs font-medium border transition-colors ${
          dark ? "bg-[#171A21] border-gray-800 text-gray-300" : "bg-gray-100 border-gray-300 text-gray-600"
        }`}
      >
        {dark ? <Sun className="h-3.5 w-3.5" /> : <Moon className="h-3.5 w-3.5" />}
        {dark ? "الوضع النهاري" : "الوضع الليلي"}
      </button>

      <div className="flex flex-col items-center text-center max-w-sm">
        {/* الشعار: علامة صلبة بلون واحد (بدون شفافية داخلية) + اسم المنصة كنص حقيقي - يضمن ظهوره دائمًا */}
        <img
          src={dark ? MARK_GOLD : MARK_TEAL}
          alt="شعار عين"
          className="w-28 h-28 object-contain mb-5"
        />

        <h1 className={`text-3xl font-extrabold mb-1 ${dark ? "text-gray-100" : "text-gray-800"}`}>
          <span className="ain-accent-text">عين</span> .. لخدمة المتطوعين
        </h1>
        <p className={`text-sm mb-10 ${dark ? "text-gray-500" : "text-gray-400"}`}>
          وحدة التحكم بفريق العيون التطوعي
        </p>

        <button className="ain-accent-solid flex items-center gap-2 rounded-2xl px-10 py-3.5 text-base font-bold transition-opacity hover:opacity-90 shadow-sm">
          انطلق
          <ArrowLeft className="h-5 w-5" />
        </button>
      </div>
    </div>
  );
}
